CREATE OR REPLACE FUNCTION pickup_slot_is_free(p_restaurant uuid,p_slot timestamptz) RETURNS bool LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$ DECLARE v_capacity int; v_used int; BEGIN IF p_slot IS NULL OR extract(epoch FROM p_slot)::bigint%900<>0 THEN RETURN false; END IF; SELECT r.pickup_slot_capacity INTO v_capacity FROM restaurants r WHERE r.id=p_restaurant AND r.is_active; IF v_capacity IS NULL OR NOT is_open_between(p_restaurant,p_slot,p_slot+interval '15 minutes') THEN RETURN false; END IF; SELECT count(*) INTO v_used FROM pickup_orders po WHERE po.restaurant_id=p_restaurant AND po.status IN('new','confirmed','preparing','ready') AND po.ready_at>=p_slot AND po.ready_at<p_slot+interval '15 minutes'; RETURN v_used<v_capacity; END $$;
